package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.*;import java.io.*;
@WebServlet("/admin/categories") public class AdminCategoriesServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{WebSupport.requireAdmin(r);PlantDao d=new PlantDao();r.setAttribute("families",d.listFamilies());r.setAttribute("genera",d.listGenera());WebSupport.view(r,s,"admin/categories");}catch(Exception e){WebSupport.error(r,s,e,"科属信息暂时不可用。");}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{WebSupport.requireAdmin(r);PlantDao d=new PlantDao();String action=r.getParameter("action");if("deleteFamily".equals(action)){long id=Long.parseLong(r.getParameter("id"));if(!d.deleteFamily(id))throw new IllegalArgumentException("该科仍有属关联，或记录不存在；请先处理关联属。");new AuditDao().log(WebSupport.user(r).getId(),"DELETE","family",id,"Family deleted",r.getRemoteAddr());}else if("deleteGenus".equals(action)){long id=Long.parseLong(r.getParameter("id"));if(!d.deleteGenus(id))throw new IllegalArgumentException("该属仍被植物使用，或记录不存在；请先移除植物关联。");new AuditDao().log(WebSupport.user(r).getId(),"DELETE","genus",id,"Genus deleted",r.getRemoteAddr());}else if("family".equals(action)){String zh=r.getParameter("familyZh"),latin=r.getParameter("familyLatin");if(zh==null||zh.isBlank()||zh.length()>100||latin!=null&&latin.length()>160)throw new IllegalArgumentException("科名长度无效。");d.createFamily(zh.trim(),latin);}else{long family=Long.parseLong(r.getParameter("familyId"));String zh=r.getParameter("genusZh"),latin=r.getParameter("genusLatin");if(latin==null||latin.isBlank()||latin.length()>120||zh!=null&&zh.length()>100)throw new IllegalArgumentException("属名长度无效。");d.createGenus(family,zh,latin);}if("family".equals(action)||"genus".equals(action))new AuditDao().log(WebSupport.user(r).getId(),"CREATE",action, null,"Taxonomy created",r.getRemoteAddr());r.getSession().setAttribute("flash","分类信息已更新。");s.sendRedirect(r.getContextPath()+"/admin/categories");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,s);}}}
